var length = tw.local.recondicionamento.orcamentos.listLength;

tw.local.orcamentoAnterior = new tw.object.Orcamento();
tw.local.orcamentoAux      = new tw.object.Orcamento();
tw.local.orcamentoAux      = tw.local.recondicionamento.orcamentos[length-1]; //tw.system.serializer.fromXml(tw.local.recondicionamento.orcamentos[length-1].toXML());  
tw.local.orcamentoAnterior = tw.local.recondicionamento.orcamentos[length-1]; 

//limpar decisao de aprovação da secretaria comercial (Sem Decisao) 
tw.local.decisao = new tw.object.NameValuePair();
tw.local.decisao.value = "SC_SD";

tw.local.reorcamento = false;
tw.local.labelReorcamentar = "SC_NULL_LABEL";

if (tw.local.orcamentoAux.comentariosReorcamentacao != null && 
    tw.local.orcamentoAux.comentariosReorcamentacao != ""   && 
    tw.local.orcamentoAux.comentariosReorcamentacao != "\r" ){

    tw.local.orcamentoAux.observacoesAutorizacao    = "\r";    
    tw.local.labelReorcamentar = "SC_RORC_LABEL";
    tw.local.reorcamento = true;
    if(tw.local.recondicionamento.orcamentos[length-2] != undefined &&
       tw.local.recondicionamento.orcamentos[length-2] != null       ){     

       tw.local.orcamentoAnterior = tw.system.serializer.fromXml(tw.local.recondicionamento.orcamentos[length-2].toXML()); 
    }
}


//tw.local.reorcamento       = false;

var length = tw.local.recondicionamento.orcamentos.listLength;

tw.local.orcamentoAux.dataAutorizacao = new tw.object.Date();

//adicionar os cometarios da aprovação e a respetiva data, aos comentarios de reorçamentação                   
if (tw.local.recondicionamento.status.value == "RORC"){

    //não existe este formato 'dd/MM/yyyy H:m' na biblioteca utilizada no parse
    var dataComentario =  tw.local.orcamentoAux.dataAutorizacao.format();   

    if( tw.local.orcamentoAux.comentariosReorcamentacao != null && tw.local.orcamentoAux.comentariosReorcamentacao != "" && tw.local.orcamentoAux.comentariosReorcamentacao != "\r"){
        tw.local.orcamentoAux.comentariosReorcamentacao = tw.local.orcamentoAux.comentariosReorcamentacao + "\n" + tw.local.orcamentoAux.observacoesAutorizacao+"\r\n["+dataComentario+"]\n";
    }
    else{
        tw.local.orcamentoAux.comentariosReorcamentacao = tw.local.orcamentoAux.observacoesAutorizacao+"\r\n["+dataComentario+"]\n";
    }
}

//copiar o objecto de orçamento da user interface para o business object
tw.local.recondicionamento.orcamentos[length-1] = tw.system.serializer.fromXml(tw.local.orcamentoAux.toXML()); 

//se não for aprovado, criar novo orçamento na lista
if (tw.local.recondicionamento.status.value != "RA"){
    tw.local.recondicionamento.orcamentos[length]   = new tw.object.Orcamento();  
    length = tw.local.recondicionamento.orcamentos.listLength;     
    tw.local.recondicionamento.orcamentos[length-1] = tw.local.orcamentoAux;
    tw.local.recondicionamento.orcamentos[length-1].autorizacao   = false;  
    tw.local.recondicionamento.orcamentos[length-1].naoOrcamentar = false;  
    tw.local.recondicionamento.orcamentos[length-1].dataAutorizacao = new tw.object.Date();

    if (tw.local.recondicionamento.status.value == "RNA" || tw.local.recondicionamento.status.value == "RPIPE"){

        tw.local.recondicionamento.transporteEntrega.dataTransporte = new tw.object.Date();
        tw.local.recondicionamento.dataFechoPedido = new tw.object.Date();
        tw.local.recondicionamento.resultadoProcesso = "completo_rejeitado";         
    }
}

//se for aprovado 
else{
    tw.local.recondicionamento.orcamentos[length-1].autorizacao  = true;
    tw.local.recondicionamento.dataAutorizacao = new tw.object.Date();
    tw.local.recondicionamento.dataAutorizacao.setTime(tw.local.orcamentoAux.dataAutorizacao.getTime());   

 }

