function toScTimeStamp(dataAux){
      var value;
    if(dataAux == undefined ||
	   dataAux == null      ){
       value = null;
    }
    else{
        value =  dataAux.getFullYear()+ "-";
        value += (Number(dataAux.getMonth()+1 < 10) ? "0"+ Number(dataAux.getMonth()+1) : Number(dataAux.getMonth()+1) )+ "-"; 
        value += (dataAux.getDate() < 10 ? "0"+ dataAux.getDate() : dataAux.getDate()) + " ";
        value += (dataAux.getHours() < 10 ? "0" + dataAux.getHours() : dataAux.getHours() ) + ":"; 
        value += (dataAux.getMinutes() < 10 ? "0"+ dataAux.getMinutes() : dataAux.getMinutes() )+ ":00";   
   }
   return value; 
}

